add(id=33, title="Common-effect models: inverse variance, Mantel-Haenszel and Peto", last_verified=V, prerequisites=["Modules 28, 32"],
 objectives=["State what the common-effect model assumes and what it estimates.", "Use inverse-variance, Mantel-Haenszel and Peto methods appropriately.", "Explain why 'fixed-effect' and 'common-effect' are used for the same model and why the term matters."],
 why="The common-effect model is simple and, for sparse binary data, MH/Peto avoid corrections - but it is only meaningful if one shared true effect is plausible.",
 plain="""**Common-effect** (often called *fixed-effect*): all studies estimate **one** true effect; differences are sampling error. Inverse-variance pooling weights by 1/variance. **Mantel-Haenszel (MH)** pools 2×2 tables directly (OR, RR or RD) and works well with few events and zero cells. **Peto** pools one-step log odds ratios; good for rare events with balanced arms and modest effects, biased otherwise. 'Fixed-effect' does not mean the effect is fixed in nature; 'common-effect' states the assumption more clearly (Borenstein et al. 2010).""",
 intermediate="""Use common-effect when it is *a priori* plausible that studies are functionally identical (e.g. replicate multi-centre trials with one protocol) or when your question is explicitly about *these* studies only. Otherwise heterogeneity usually calls for random effects and a prediction interval. MH/Peto assume homogeneity of the *relative* effect; Q still reports heterogeneity. In simulation work on rare events MH-type methods often perform better than inverse-variance with continuity corrections (Bradburn et al. 2007; cited as further reading). MetaLab's MH/Peto use uncorrected tables, matching R metafor.""",
 advanced="""MH variance estimators (Robins-Breslow-Greenland for OR; Greenland-Robins for RR; Sato et al. for RD in metafor) are consistent under both sparse and large-stratum asymptotics. Peto's one-step estimate approximates the log OR via O−E over V and degrades with large effects (OR far from 1) or unequal group sizes. Common-effect is a special case of random effects with τ²=0; reporting both can be informative, but choose by principle, not by Q or I².""",
 assumptions=["One shared true effect (or an explicit 'these studies only' question).","Independent studies.","Peto: rare events, balanced arms, modest effects."],
 worked_example="""BCG trials (13 studies, R/metafor): common-effect IV pooled log RR = **−0.430** (RR 0.65, 95% CI 0.60-0.70), τ²=0. Random-effects REML: log RR = **−0.7145** (RR 0.49, CI 0.34-0.70). Mantel-Haenszel OR = **0.623** (0.575-0.675); Peto OR = **0.622** (0.575-0.674). The common-effect CIs are narrow because heterogeneity is ignored (Q is huge) - the models answer different questions: 'effect in these trials' vs 'mean of a distribution of effects'.""",
 examples=[("Clinical","Rare adverse events: MH/Peto."),("Preclinical","Replicate lab experiments with one protocol."),("Plant","Single-protocol multi-site trials."),("Microbiology","Count data with many zeros."),("Education","Multi-site trials with one curriculum.")],
 mistakes=["Choosing common-effect because I² is low.","Peto with large effects.","Applying correction before MH.","Interpreting a narrow CI as proof of homogeneity."],
 misconceptions=[("'Fixed effect means the effect never varies.'","It is an assumption about the model."),("'Common-effect is more powerful, so prefer it.'","It is more precise only if its assumption holds.")],
 controversies=["Fixed vs random as default.","Peto bias thresholds."],
 decision_tree=[("One shared effect plausible a priori?","Yes -> common-effect OK; No -> random effects."),("Sparse binary data?","MH/Peto + sensitivity."),("Large effects/unbalanced arms?","Avoid Peto.")],
 exercises=["Run MH and Peto on the BCG data in the Statistics Lab (Advanced methods).","Explain why the common-effect CI is narrower than the random-effects CI.","Write the model justification sentence for your protocol."],
 integrity="Do not switch from common to random (or back) after seeing results.", further=["borenstein2010","bradburn2007","viechtbauer2010","sweeting2004"],
 coding=dict(r='library(metafor)\nrma.mh(ai=tpos, bi=tneg, ci=cpos, di=cneg, data=dat.bcg, measure="OR")\nrma.peto(ai=tpos, bi=tneg, ci=cpos, di=cneg, data=dat.bcg)', python='import numpy as np\nfrom metalab import advanced as A\nfrom metalab.datasets import BCG\na,b,c,d = map(np.array, zip(*BCG))\nr = A.mantel_haenszel(a,b,c,d,"OR"); print(np.exp(r["est"]), np.exp(r["ci"]))'),
 application="**Milestone 10:** state the model in the SAP; run common-effect only if pre-specified; use MH/Peto for sparse binary data with sensitivity.", checklist=["Model justified a priori","MH/Peto assumptions checked","Heterogeneity reported"],
 quiz=[dict(q="Common-effect assumes...", opts=["One shared true effect","Effects vary randomly","No sampling error","Large n"], ans=0, why="Definition."),
  dict(q="Peto's method is least appropriate when...", opts=["Effects are large or arms unbalanced","Events are rare","Effects are small","Arms are balanced"], ans=0, why="Bias."),
  dict(q="MH uses...", opts=["Uncorrected 2×2 tables (valid with zero cells)","Only continuous data","Random effects","Meta-regression"], ans=0, why="As metafor."),
  dict(q="A narrow common-effect CI with huge Q indicates...", opts=["Precision that ignores heterogeneity","Homogeneity","No bias","Good power"], ans=0, why="Misleading."),
  dict(q="'Fixed-effect' and 'common-effect' are...", opts=["Names for the same model","Different models","Bayesian","Network"], ans=0, why="Borenstein 2010.")])

add(id=34, title="Random-effects models: estimators, CIs and prediction intervals", last_verified=V, prerequisites=["Modules 32, 35"],
 objectives=["Compare REML, PM and DL estimates and their behaviour.", "Choose a CI method (Wald vs Hartung-Knapp) and report prediction intervals.", "Handle few studies responsibly."],
 why="Estimator and CI choices change results most when k is small - the usual situation in lab biology.",
 plain="""Random-effects assumes true effects vary: θᵢ ~ N(μ, τ²). The pooled estimate estimates μ. Estimators of τ²: **REML**, **Paule-Mandel (PM)**, **DerSimonian-Laird (DL)**. CIs: **Wald** (normal) or **Hartung-Knapp-Sidik-Jonkman (HKSJ)** (t with k−1 df, adjusted variance). Always add a **prediction interval**.""",
 intermediate="""No estimator is universally best (Veroniki 2016; Langan 2019): REML is a reasonable default in many settings; PM performs well but can be positively biased with very unequal study sizes; DL can be negatively biased with small or sparse studies. HKSJ tends to have better coverage with few studies (Hartung & Knapp 2001; IntHout et al. 2014 examine it further). **Pre-specify** the estimator and run a sensitivity analysis. Report τ² with a confidence interval (Q-profile) - it is uncertain.""",
 advanced="""HKSJ can give intervals narrower than Wald when q*<1; some software truncates (not metafor's default). Random-effects weights 1/(vᵢ+τ²) assume known vᵢ - an approximation for SMD/log OR. With k<5, consider presenting studies individually plus an HKSJ interval and a cautious prediction interval.""",
 assumptions=["Independent studies.","True effects ~ roughly normal.","Variances treated as known."],
 worked_example="""BCG trials (13 studies; R/metafor): REML log RR **−0.7145** (τ²=0.3132); PM **−0.7150** (τ²=0.3181); DL **−0.7141** (τ²=0.3088) - estimates agree closely here. Wald 95% CI (REML) −1.067 to −0.362; HKSJ CI **−1.108 to −0.321** (wider). The Riley prediction interval for RR runs from **0.13 to 1.78**.""",
 examples=[("Preclinical","Few labs, large τ²."),("Clinical","HKSJ for k<10."),("Ecology","Multilevel needed for dependence."),("Education","Classroom clustering."),("Psychology","Replications.")],
 mistakes=["Choosing the estimator after seeing results.","Wald CI with k=4.","No prediction interval.","Treating τ² as precise."],
 misconceptions=[("'Random effects fixes small-study bias.'","It can amplify it."),("'REML is always best.'","Conditions apply.")],
 controversies=["Best estimator.","Default HKSJ."],
 decision_tree=[("k<10?","HKSJ + cautious τ²."),("Unequal sizes?","Sensitivity with PM/DL."),("Dependence?","Use multilevel/robust (Module 38-40).")],
 exercises=["Fit REML, PM, DL on your data and compare.","Compute HKSJ vs Wald CIs.","Write the estimator sentence for your SAP."],
 integrity="Pre-specify estimator and CI method; report sensitivity.", further=["veroniki2016","langan2019","hartung2001","inthout2014","viechtbauer2005","riley2011"],
 coding=dict(r='library(metafor)\ndat <- escalc(measure="RR", ai=tpos, bi=tneg, ci=cpos, di=cneg, data=dat.bcg)\nfor (m in c("REML","PM","DL")) print(rma(yi, vi, data=dat, method=m))\nrma(yi, vi, data=dat, method="REML", test="knha")', python='import numpy as np\nfrom metalab import stats as S\nfrom metalab.datasets import BCG\nys, vs = zip(*[S.log_risk_ratio(a,a+b,c,c+d) for a,b,c,d in BCG])\nfor m in ("REML","PM","DL"): print(m, S.meta_analyze(ys, vs, "random", m).tau2)'),
 application="**Milestone 10:** specify estimator + CI + prediction interval; run sensitivity with PM.", checklist=["Estimator pre-specified","CI method stated","PI reported","Sensitivity run"],
 quiz=[dict(q="Which CI tends to have better coverage with few studies?", opts=["HKSJ","Wald","None","Bayesian only"], ans=0, why="Hartung & Knapp; Langan 2019."),
  dict(q="DL estimator is known to be...", opts=["Biased low in some small/sparse settings","Always best","Biased high always","Irrelevant"], ans=0, why="Langan 2019."),
  dict(q="Random-effects pooled value estimates...", opts=["Mean of true effects","One true effect","Largest effect","Median"], ans=0, why="μ."),
  dict(q="BCG REML τ² (R)?", opts=["0.313","0.031","3.13","0"], ans=0, why="R/metafor output.", numeric=True),
  dict(q="Report τ² with...", opts=["An uncertainty interval","Nothing","A p-value only","Rounding"], ans=0, why="Q-profile.")])

add(id=36, title="Subgroup analysis: pre-specification and the test for interaction", last_verified=V, prerequisites=["Module 35"],
 objectives=["Pre-specify few subgroups with direction.", "Test subgroup differences formally.", "Avoid the 'significant here, not there' fallacy."],
 why="Subgroup claims are among the most misleading in the literature.",
 plain="""A subgroup analysis compares effects between groups of studies. Rules: **pre-specify** a few subgroups with a stated hypothesis; use a **test for subgroup differences** (interaction), not separate p-values; remember that studies differ in many ways (confounding across studies); with few studies power is low. Oxman & Guyatt (1992) set out a classic checklist for judging subgroup claims.""",
 intermediate="""Two approaches: separate τ² per subgroup (Q-between on subgroup estimates) or a common τ² mixed-effects moderator test (metafor-style). With few studies per subgroup, separate τ² is unstable. Multiple subgroups inflate false positives; adjust interpretation. Subgroup differences are *observational* across studies.""",
 advanced="""Credibility criteria (e.g. Sun et al. 2010 and later refinements) weigh pre-specification, within- vs between-study comparisons, biological plausibility and consistency. For preclinical work, sex subgroups can often be compared *within* studies, which is stronger than between-study contrasts.""",
 assumptions=["Subgroups pre-specified.","Adequate studies per subgroup.","Independence."],
 worked_example="""BCG trials by allocation method (R/metafor, REML): random (k=7) −0.971; alternate (k=2) −0.541; systematic (k=4) −0.424. Common-τ² moderator test: QM=**1.768**, p=**0.413** - no evidence that allocation method modifies the effect, despite visibly different estimates (note k=2 for alternate).""",
 examples=[("Preclinical","Sex, genotype."),("Clinical","Age group."),("Ecology","Biome."),("Education","Grade level."),("Plant","Cultivar.")],
 mistakes=["Comparing p-values across subgroups.","Post-hoc subgroup hunting.","Tiny subgroups.","No interaction test."],
 misconceptions=[("'Significant in one subgroup but not the other = difference.'","Test the difference."),("'More subgroups = more insight.'","More false positives.")],
 controversies=["Separate vs common τ².","Credibility criteria."],
 decision_tree=[("Pre-specified?","If no, label exploratory."),("k per subgroup >= ~3-4?","Else skip."),("Within-study comparison possible?","Prefer it.")],
 exercises=["Run the allocation subgroup in the lab and interpret QM.","Explain why p<0.05 in one subgroup is not enough.","Pre-specify two subgroups with hypotheses."],
 integrity="Label post-hoc subgroup analyses as exploratory; report all subgroup analyses run.", further=["oxman1992","thompson2002","borenstein2010","higgins2011rob"],
 coding=dict(r='library(metafor)\ndat <- escalc(measure="RR", ai=tpos, bi=tneg, ci=cpos, di=cneg, data=dat.bcg)\nrma(yi, vi, mods=~factor(alloc), data=dat)', python='from metalab import stats as S\nfrom metalab.datasets import BCG, BCG_ALLOC\nys, vs = zip(*[S.log_risk_ratio(a,a+b,c,c+d,cc=0.5) for a,b,c,d in BCG])\nr = S.subgroup_analysis(ys, vs, BCG_ALLOC)\nprint(r["Q_between"], r["moderator_test"].QM)'),
 application="**Milestone 11:** run only pre-specified subgroups; report interaction tests.", checklist=["Subgroups pre-specified","Interaction test reported","Small subgroups flagged"],
 quiz=[dict(q="Valid evidence of a subgroup difference is...", opts=["A test of the interaction","p<0.05 in one subgroup","Larger point estimate","Visual difference"], ans=0, why="Formal test."),
  dict(q="BCG allocation subgroup test QM?", opts=["1.77 (p=0.41)","16.4","0.05","152"], ans=0, why="R/metafor.", numeric=True),
  dict(q="Post-hoc subgroups should be...", opts=["Labelled exploratory","Presented as confirmatory","Omitted from methods","Averaged"], ans=0, why="Honesty."),
  dict(q="Between-study subgroup contrasts are...", opts=["Observational and confoundable","Randomised","Causal","Unbiased"], ans=0, why="Study-level confounding."),
  dict(q="With k=2 in a subgroup...", opts=["Estimates are unstable","Estimates are exact","τ² is precise","Use more subgroups"], ans=0, why="Few studies.")])

add(id=37, title="Meta-regression: moderators, overfitting and ecological bias", last_verified=V, prerequisites=["Modules 35, 36"],
 objectives=["Fit and interpret a mixed-effects meta-regression.", "Respect study-number limits.", "Explain residual heterogeneity and R² cautiously."],
 why="Meta-regression can explain heterogeneity - or manufacture false findings.",
 plain="""Meta-regression relates effect sizes to study-level moderators (continuous or categorical). A **mixed-effects** model adds a residual τ² (heterogeneity not explained). Rules of thumb: about **10 studies per moderator**, pre-specify moderators, and treat findings as hypothesis-generating (Thompson & Higgins 2002; Baker et al. 2009).""",
 intermediate="""Output: coefficients with SE, **QM** (omnibus test of moderators), residual **τ²** and **QE**, and **R²** (proportional reduction in τ², very imprecise). With Hartung-Knapp-type tests use t/F reference distributions. Beware **ecological bias** (between-study relationships need not hold within studies), collinearity, outliers/high leverage and non-linear relationships. Centre continuous moderators to interpret the intercept.""",
 advanced="""Permutation tests can control false positives with many moderators. Model selection (stepwise) invalidates inference. In multilevel models moderators can vary at study or effect level; use appropriate random structure. MetaLab refuses models with residual df<2 or collinearity and warns below 10 studies per moderator.""",
 assumptions=["Pre-specified moderators.","Enough studies.","Linear relationship (check).","Independence."],
 worked_example="""BCG trials on absolute latitude (R/metafor REML): slope **−0.0291** per degree (SE 0.0072); QM=**16.36**, p=**5.2×10⁻⁵**; residual τ²=**0.0763** (vs total 0.3132), so R²≈**75.6%**; QE=30.73. Interpretation: trials farther from the equator show stronger protection - a hypothesis about latitude, not a causal effect, and k=13 with one moderator is near the practical limit.""",
 examples=[("Ecology","Temperature moderators."),("Preclinical","Dose, duration."),("Clinical","Baseline risk."),("Education","Intervention length."),("Plant","Stress severity.")],
 mistakes=["Many moderators with few studies.","Stepwise selection.","Reading R² as precise.","Causal language."],
 misconceptions=[("'A significant moderator explains the effect causally.'","Between-study association only."),("'More moderators = better fit.'","Overfitting.")],
 controversies=["Minimum studies per moderator.","Permutation vs asymptotic tests."],
 decision_tree=[("k/moderators >= 10?","Else restrict."),("Pre-specified?","Else exploratory."),("Outliers?","Influence analysis (Module 51).")],
 exercises=["Reproduce the latitude regression in the Statistics Lab.","Explain why R² is imprecise here.","List two ecological-bias examples."],
 integrity="Pre-specify moderators; report all moderators tested.", further=["thompson2002","baker2009","viechtbauer2010","viechtbauer2010outlier"],
 coding=dict(r='library(metafor)\ndat <- escalc(measure="RR", ai=tpos, bi=tneg, ci=cpos, di=cneg, data=dat.bcg)\nres <- rma(yi, vi, mods=~ablat, data=dat); res\nanova(res)', python='from metalab import stats as S\nfrom metalab.datasets import BCG, BCG_ABLAT\nys, vs = zip(*[S.log_risk_ratio(a,a+b,c,c+d,cc=0.5) for a,b,c,d in BCG])\nX, names = S.design_matrix(ablat=BCG_ABLAT)\nr = S.meta_regression(ys, vs, X, names); print(r.beta, r.QM, r.tau2, r.R2)'),
 application="**Milestone 11:** run pre-specified moderators only; report limitations.", checklist=["Moderators pre-specified","Studies per moderator checked","R² interpreted cautiously"],
 quiz=[dict(q="Rule of thumb for studies per moderator?", opts=["About 10","1","2","100"], ans=0, why="Cochrane guidance."),
  dict(q="BCG latitude slope (log RR per degree)?", opts=["-0.029","0.5","-3","0"], ans=0, why="R/metafor.", numeric=True),
  dict(q="R² in meta-regression is...", opts=["Imprecise, relative to total τ²","Exact","Always 100%","Unrelated to τ²"], ans=0, why="Proportion of τ² explained."),
  dict(q="Ecological bias means...", opts=["Between-study relations may not hold within studies","Bias from ecology","Sampling error","Random error"], ans=0, why="Aggregate data."),
  dict(q="Stepwise moderator selection...", opts=["Invalidates inference","Is recommended","Is required","Improves power"], ans=0, why="Selection bias.")])

add(id=50, title="Publication bias and small-study effects", last_verified=V, prerequisites=["Modules 35, 32"],
 objectives=["Interpret funnel plots, Egger and Begg tests correctly.", "Explain why asymmetry is not proof of publication bias.", "Know what is and is not implemented."],
 why="Missing studies can distort pooled estimates; but the tools are weak and often over-interpreted.",
 plain="""**Publication bias**: results are more likely to be published when significant. **Small-study effects**: smaller studies show different (often larger) effects - which may be due to publication bias, heterogeneity, chance or methodological differences. A **funnel plot** plots effect against precision; asymmetry is a *signal*. Tests: Egger regression, Begg rank correlation.""",
 intermediate="""Sterne et al. (2011) give recommendations: test only with ≥10 studies, interpret cautiously, consider the effect measure (some, like log OR, induce artefactual asymmetry), and explore other explanations. Page et al. (2020) review methods for investigating reporting biases; Egger et al. (1997) is the classic regression test. Methods such as trim-and-fill, selection models and PET-PEESE make strong assumptions and are not implemented in MetaLab.""",
 advanced="""Outcome-reporting bias (selective reporting within studies) differs from publication bias; check protocols/registries. In ecology and preclinical science, published meta-analyses often show small-study effects; consider time-lag bias and multilevel structure (tests ignoring dependence mislead).""",
 assumptions=["k>=10 for tests.","Independence.","Effect measure free of mean-variance artefacts."],
 worked_example="""BCG trials (k=13, log RR): Egger t=**−1.40** (df 11), p=**0.189**; Begg τ=0.026, exact p=**0.952**. No evidence of asymmetry - which does *not* prove absence of publication bias (low power, strongly heterogeneous trials).""",
 examples=[("Preclinical","Many small positive studies."),("Clinical","Registered-trial comparison."),("Ecology","Time-lag bias."),("Psychology","p-curve discussions."),("Education","Small-study effects.")],
 mistakes=["Egger with k<10.","Equating asymmetry with bias.","Trim-and-fill as truth.","Ignoring selective outcome reporting."],
 misconceptions=[("'Symmetric funnel = no bias.'","Low power."),("'Asymmetry = publication bias.'","Other causes exist.")],
 controversies=["Value of trim-and-fill.","Selection models."],
 decision_tree=[("k>=10?","Else descriptive only."),("Asymmetry?","List explanations; sensitivity analyses."),("Registry data?","Compare protocols to reports.")],
 exercises=["Draw the BCG funnel plot and run tests in the lab.","List four causes of asymmetry.","Search a registry for protocols in your area."],
 integrity="Report tests run and their limitations; do not present asymmetry as proof.", further=["sterne2011funnel","egger1997","page2020bias","sterne2001"],
 coding=dict(r='library(metafor)\ndat <- escalc(measure="RR", ai=tpos, bi=tneg, ci=cpos, di=cneg, data=dat.bcg)\nres <- rma(yi, vi, data=dat)\nregtest(res, model="lm", predictor="sei")\nranktest(res)\nfunnel(res)', python='from metalab import stats as S, advanced as A\nfrom metalab.datasets import BCG\nys, vs = zip(*[S.log_risk_ratio(a,a+b,c,c+d,cc=0.5) for a,b,c,d in BCG])\nprint(A.egger_test(ys, vs)["p"], A.begg_test(ys, vs)["p"])'),
 application="**Milestone 11:** funnel plot + tests only if k>=10; discuss alternatives.", checklist=["k checked","Alternatives listed","No over-claiming"],
 quiz=[dict(q="Funnel asymmetry proves publication bias.", opts=["True","False - other explanations exist","Only if p<0.05","Only for OR"], ans=1, why="Sterne 2011."),
  dict(q="Minimum studies recommended for asymmetry tests?", opts=["About 10","2","3","50"], ans=0, why="Power."),
  dict(q="BCG Egger p-value (R)?", opts=["0.189","0.001","0.95","0.5"], ans=0, why="R/metafor.", numeric=True),
  dict(q="Trim-and-fill is...", opts=["Assumption-heavy and not implemented here","Proof","Standard","Required"], ans=0, why="Strong assumptions."),
  dict(q="Selective outcome reporting is...", opts=["Distinct from publication bias","The same","Impossible","Random error"], ans=0, why="Within-study.")])

add(id=51, title="Sensitivity and influence analysis", last_verified=V, prerequisites=["Modules 32, 35"],
 objectives=["Run leave-one-out and influence diagnostics.", "Distinguish sensitivity analysis from study selection.", "Report robustness honestly."],
 why="Showing that conclusions survive reasonable alternatives is core to credibility.",
 plain="""**Leave-one-out** re-estimates the pooled effect omitting each study. **Influence diagnostics** (studentised residuals, Cook's distance, hat values) flag studies with unusual leverage or discrepancy (Viechtbauer & Cheung 2010). Other sensitivity analyses: alternative estimators, effect measures, correlation assumptions, excluding high-risk or reconstructed data.""",
 intermediate="""Flags are *prompts*: check data entry, population and design. Do not delete studies because they change significance. Pre-specify which sensitivity analyses you will run. Report all of them (e.g. in a supplementary table), including those that change conclusions.""",
 advanced="""rstudent uses the leave-one-out τ² and variance; Cook's distance measures change in the pooled estimate relative to its variance. With few studies all diagnostics are unstable. Baujat plots show each study's contribution to heterogeneity vs influence.""",
 assumptions=["Analyses pre-specified.","Flags investigated, not used to delete."],
 worked_example="""BCG REML leave-one-out: externally studentised residuals range from about −1.45 to 1.45 (none beyond ±2). No single trial drives the estimate or heterogeneity. Using the Statistics Lab -> Influence diagnostics you can verify.""",
 examples=[("Preclinical","Exclude reconstructed data."),("Clinical","Exclude high-risk trials."),("Ecology","Exclude outlying sites."),("Education","Alternative ES."),("All","Alternative estimator.")],
 mistakes=["Deleting outliers for p<0.05.","Unplanned analyses presented as planned.","Reporting only reassuring analyses."],
 misconceptions=[("'Outlier = error.'","May be real heterogeneity."),("'Leave-one-out proves robustness.'","Only against single-study removal.")],
 controversies=["Thresholds for flags.","Winsorising."],
 decision_tree=[("Flagged?","Check data; keep unless error."),("Conclusion changes?","Report transparently."),("Pre-specified?","Label.")],
 exercises=["Run influence diagnostics on your data.","Write a pre-specified list of sensitivity analyses.","Explain why a flagged study is not removed automatically."],
 integrity="Never exclude studies post hoc to change significance; report all sensitivity analyses.", further=["viechtbauer2010outlier","higgins2011rob","borenstein2010"],
 coding=dict(r='library(metafor)\ndat <- escalc(measure="RR", ai=tpos, bi=tneg, ci=cpos, di=cneg, data=dat.bcg)\nres <- rma(yi, vi, data=dat)\nleave1out(res)\ninfluence(res)', python='from metalab import stats as S, advanced as A\nfrom metalab.datasets import BCG\nys, vs = zip(*[S.log_risk_ratio(a,a+b,c,c+d,cc=0.5) for a,b,c,d in BCG])\nprint([round(r["rstudent"],2) for r in A.influence_diagnostics(ys, vs)])'),
 application="**Milestone 11:** run the pre-specified sensitivity set; report all results.", checklist=["Sensitivity set pre-specified","Flags investigated","All results reported"],
 quiz=[dict(q="A flagged influential study should be...", opts=["Investigated, then kept unless erroneous","Deleted","Hidden","Duplicated"], ans=0, why="Prompt, not rule."),
  dict(q="Leave-one-out shows...", opts=["Sensitivity to single studies","Bias","Causality","Publication bias"], ans=0, why="Definition."),
  dict(q="Sensitivity analyses should be...", opts=["Pre-specified and fully reported","Chosen after results","Selective","Secret"], ans=0, why="Transparency."),
  dict(q="Cook's distance measures...", opts=["Influence on the pooled estimate","Heterogeneity","Bias","Precision"], ans=0, why="Change in estimate."),
  dict(q="Excluding reconstructed data tests...", opts=["Robustness to uncertain data","Publication bias","τ²","Nothing"], ans=0, why="Sensitivity.")])

add(id=52, title="Certainty of evidence: GRADE and its limits outside clinical medicine", last_verified=V, prerequisites=["Modules 22, 35"],
 objectives=["Name GRADE domains and how they rate certainty.", "Explain why clinical frameworks need adaptation elsewhere.", "Present certainty transparently."],
 why="A pooled estimate means little without a judgement of how much confidence to place in it.",
 plain="""GRADE rates certainty (high, moderate, low, very low) for each outcome, starting from study design and moving down for **risk of bias, inconsistency, indirectness, imprecision, publication bias** (and up in specific situations). Guyatt et al. (2008) introduced the approach; later 'GRADE guidelines' papers detail each domain (e.g. Balshem et al. 2011 on rating quality of evidence). Results are presented in **Summary of Findings** tables.""",
 intermediate="""GRADE was built for health interventions and guideline development; applying it to animal, plant or ecological evidence needs careful adaptation: *indirectness* (translation from model organism to humans, lab to field) and the starting rating differ. Some fields use discipline-specific frameworks. If you adapt GRADE, state exactly what you changed and why, and avoid claims of 'GRADE-assessed' without following the guidance. Judgements are transparent but subjective.""",
 advanced="""Imprecision uses CI width relative to a decision threshold (optimal information size); inconsistency uses heterogeneity and prediction intervals; publication bias is difficult to prove or rule out. Network meta-analysis and qualitative evidence have their own extensions (CINeMA, GRADE-CERQual).""",
 assumptions=["Per-outcome assessment.","Explicit rationale for each downgrade."],
 worked_example="""Fly lifespan outcome, 6 lab experiments: risk of bias unclear (not downgraded? or serious - rationale needed); inconsistency: large τ² and wide prediction interval (downgrade); indirectness: lifespan in flies to human ageing (serious for human relevance; not for fly questions); imprecision: CI includes small benefit and harm (downgrade). State each judgement and the reasoning; do not report a number-of-stars without it.""",
 examples=[("Clinical","Standard GRADE."),("Preclinical","Adapted GRADE; translation indirectness."),("Ecology","Discipline frameworks."),("Qualitative","GRADE-CERQual."),("Network MA","CINeMA.")],
 mistakes=["Adopting GRADE labels without guidance.","No rationale.","Ignoring indirectness.","One rating for all outcomes."],
 misconceptions=[("'GRADE gives objective ratings.'","Transparent judgements."),("'High certainty = true.'","Confidence, not truth.")],
 controversies=["GRADE outside health.","Treatment of observational evidence."],
 decision_tree=[("Health intervention?","Standard GRADE."),("Other discipline?","Adapt/transparently justify or use field framework."),("Per outcome?","Yes.")],
 exercises=["Draft certainty judgements for your primary outcome with reasons.","List adaptation issues for your discipline.","Build a SoF-style table."],
 integrity="Do not claim GRADE assessment unless you followed the guidance; explain adaptations.", further=["guyatt2008","balshem2011","inthout2016"],
 application="**Milestone 12:** write certainty judgements with explicit rationale.", checklist=["Per-outcome assessment","Rationale for each domain","Adaptations stated"],
 quiz=[dict(q="GRADE downgrade domains include...", opts=["Risk of bias, inconsistency, indirectness, imprecision, publication bias","Only sample size","Only p-values","Only journal"], ans=0, why="Standard."),
  dict(q="Applying GRADE to fly studies requires...", opts=["Explicit adaptation and rationale","Nothing","Removing domains silently","Calling it validated"], ans=0, why="Context."),
  dict(q="Certainty rating is assessed...", opts=["Per outcome","Once per review","Per journal","Per author"], ans=0, why="Outcome-specific."),
  dict(q="High certainty means...", opts=["High confidence the effect estimate is close to truth","Truth","Large n","p<0.05"], ans=0, why="Confidence."),
  dict(q="Imprecision relates to...", opts=["CI width vs decision threshold","Bias","Publication","Indirectness"], ans=0, why="Domain.")])

add(id=74, title="Interpretation and communication of results", last_verified=V, prerequisites=["Modules 35, 52"],
 objectives=["Report estimates with uncertainty and prediction intervals.", "Distinguish statistical, biological and practical significance.", "Write null findings and plain-language summaries without exaggeration."],
 why="Most misinterpretation happens in the Discussion, not the analysis.",
 plain="""Report the **effect size with CI** and (random effects) the **prediction interval** (IntHout et al. 2016 argue for routinely presenting them). Translate effect sizes into meaningful units (e.g. +4 days of lifespan; a 20% proportional increase). Interpret in light of certainty of evidence, heterogeneity and study limitations. A non-significant result is *inconclusive* unless the CI excludes meaningful effects.""",
 intermediate="""Avoid causal language beyond the designs (between-study moderators are associations). Avoid 'no effect' for p>0.05; state the range of effects compatible with the data. Describe generalisability (species, strain, sex, lab, environment). Provide a plain-language summary stating what was done, found and what remains uncertain.""",
 advanced="""Biological significance requires a justified threshold (e.g. a minimally important lifespan change); a 2% effect may be statistically clear and biologically trivial. Communicating to policymakers requires explicit certainty statements. Pre-register interpretive thresholds where possible.""",
 assumptions=["Certainty and limitations accompany every conclusion."],
 worked_example="""BCG: pooled RR 0.49 (95% CI 0.34-0.70) - on average BCG halves TB risk; prediction interval 0.13-1.78 - in a new setting the vaccine could be strongly protective or ineffective; latitude explains much heterogeneity. Good conclusion: 'protection varied widely across trials, largest at higher latitudes (association across trials)'.""",
 examples=[("Preclinical","Lifespan change in days and %."),("Clinical","Absolute risk reduction."),("Ecology","Proportional change."),("Education","Standardised gain."),("Policy","Plain-language summary.")],
 mistakes=["'No effect' from p>0.05.","Ignoring prediction intervals.","Causal language for moderators.","Overgeneralising species."],
 misconceptions=[("'Significance = importance.'","Magnitude and context matter."),("'A narrow CI = certainty.'","Bias remains.")],
 controversies=["Routine PIs.","Thresholds for importance."],
 decision_tree=[("CI includes meaningful effects both ways?","Inconclusive."),("PI wide?","State context dependence."),("Low certainty?","Hedge language.")],
 exercises=["Rewrite a conclusion without causal over-reach.","Write a 100-word plain-language summary.","State a minimally important effect for your outcome and justify."],
 integrity="Do not exaggerate; communicate uncertainty and limitations.", further=["inthout2016","riley2011","guyatt2008","page2021ee"],
 application="**Milestone 12:** write conclusions with every claim traced to a verified result.", checklist=["Effect + CI + PI","Certainty stated","Limitations listed","No causal over-reach"],
 quiz=[dict(q="p>0.05 and a wide CI means...", opts=["Inconclusive","No effect","Proof of no effect","Bias"], ans=0, why="Absence of evidence."),
  dict(q="A prediction interval describes...", opts=["Where a new study's true effect may lie","Pooled mean","Bias","Power"], ans=0, why="Riley 2011."),
  dict(q="Between-study moderator findings are...", opts=["Associations","Causal","Randomised","Proof"], ans=0, why="Observational."),
  dict(q="Biological significance requires...", opts=["A justified importance threshold","p<0.05","Large n","Journal approval"], ans=0, why="Context."),
  dict(q="Plain-language summaries should state...", opts=["What was found and uncertainty","Only positives","Only p","Nothing"], ans=0, why="Honesty.")])

add(id=75, title="Scientific writing for evidence syntheses", last_verified=V, prerequisites=["Modules 7, 16, 74"],
 objectives=["Structure a review manuscript following PRISMA 2020.", "Write Methods/Results only from verified outputs.", "Include data/code availability and AI-use disclosure."],
 why="Clear, complete reporting lets others evaluate and reuse your work.",
 plain="""Structure: Title (identify as systematic review/meta-analysis), structured abstract, Introduction (rationale, objectives with PICO), Methods (protocol/registration, eligibility, sources, search, selection, extraction, RoB, synthesis, certainty), Results (flow, characteristics, RoB, syntheses, sensitivity, reporting biases, certainty), Discussion (interpretation, limitations, implications), declarations (funding, conflicts, registration, **data and code availability**, **AI-use disclosure** per journal policy). PRISMA 2020 (Page et al. 2021a,b) lists 27 items.""",
 intermediate="""Write Methods from the frozen protocol and report deviations. Populate Results only from stored outputs (MetaLab's Manuscript Studio refuses unverified values). Provide supplementary search strategies and extraction/analysis data. Keep claims tied to results; cite verified references.""",
 advanced="""Reporting checklists do not replace methodological rigour (a perfectly reported poor review is still poor). For reproducibility, deposit data and code in a repository with a DOI and state software versions. Declare tools used for writing assistance and verify every statement and citation yourself.""",
 assumptions=["Protocol and outputs are archived.","Every number is traceable."],
 worked_example="""Methods sentence: 'We searched PubMed and Europe PMC on 2026-xx-xx (queries in Supplement S1). Two reviewers screened... [or: One reviewer screened; a second verified 20%].' Results sentence: 'Of 120 records, 20 duplicates were removed; 100 screened; 8 studies were included (Figure 1).' Each number comes from the PRISMA counts and search log.""",
 examples=[("Clinical","PRISMA + registered protocol."),("Preclinical","Plus animal-study reporting details."),("Ecology","ROSES/PRISMA."),("Qualitative","ENTREQ."),("Scoping","PRISMA-ScR.")],
 mistakes=["Results not matching tables.","Hidden deviations.","No data/code statement.","Undisclosed AI use.","Unverified citations."],
 misconceptions=[("'The abstract can be written first.'","Write after results are final."),("'PRISMA compliance = quality.'","It is reporting only.")],
 controversies=["Level of detail in Methods.","AI writing-assistance policies."],
 decision_tree=[("Number in text?","Trace to stored output."),("Deviation from protocol?","Report."),("AI assistance?","Disclose per policy; verify.")],
 exercises=["Draft Methods from your protocol.","Trace five numbers to sources.","Complete a PRISMA 2020 checklist for a published review."],
 integrity="No invented results; disclose AI assistance per journal policy; verify every citation.", further=["page2021","page2021ee","moher2015","shamseer2015"],
 application="**Milestone 13:** use the Manuscript Studio to draft sections from verified outputs only.", checklist=["Methods match protocol","Numbers traceable","Data/code statement","AI disclosure","Citations verified"],
 quiz=[dict(q="Results numbers should come from...", opts=["Stored verified outputs","Memory","Estimates","Drafts"], ans=0, why="Traceability."),
  dict(q="Does PRISMA compliance guarantee quality?", opts=["No - it is reporting guidance","Yes","Only for RCTs","Only with registration"], ans=0, why="Reporting≠conduct."),
  dict(q="Deviations from protocol should be...", opts=["Reported","Hidden","Deleted","Rephrased"], ans=0, why="Transparency."),
  dict(q="AI writing assistance should be...", opts=["Disclosed per journal policy and verified","Hidden","Cited as author","Used for results"], ans=0, why="Integrity."),
  dict(q="PRISMA 2020 checklist has how many items?", opts=["27","10","50","5"], ans=0, why="Page 2021a.")])

add(id=76, title="Reporting guidelines directory: which one for which review", last_verified=V, prerequisites=["Module 75"],
 objectives=["Select the reporting guideline matching the review type.", "Use EQUATOR to find guidelines.", "Explain why reporting guidelines are not quality tools."],
 why="Using the right guideline makes reviews complete and comparable.",
 plain="""Choose by design: **PRISMA 2020** (systematic reviews; Page 2021), **PRISMA-P** (protocols; Shamseer 2015/Moher 2015), **PRISMA-S** (searches; Rethlefsen 2021), **PRISMA-ScR** (scoping; Tricco 2018), **PRISMA-DTA** (diagnostic accuracy; McGrath 2019 describes it), **PRISMA-NMA** (network meta-analysis; Hutton 2015), **PRISMA-IPD** (individual participant data; Stewart 2015), **MOOSE** (observational; Stroup 2000), **SWiM** (synthesis without meta-analysis; Campbell 2020), **ENTREQ** (qualitative synthesis; Tong 2012), **ROSES** (environmental syntheses; Haddaway 2018). The EQUATOR Network library helps locate others and current versions.""",
 intermediate="""Check each guideline's *current* version on the official site before use. A checklist is completed by locating each item in your manuscript; mark 'not applicable' with a reason. Reporting guidelines are not risk-of-bias tools and do not make a review rigorous.""",
 advanced="""Extensions evolve; PRISMA 2020 replaced the 2009 statement. Some journals require checklist upload and registration details. For animal or plant primary studies, reporting guidelines (e.g. ARRIVE) concern *primary* studies, not your review.""",
 assumptions=["You use the current official version."],
 worked_example="""Fly-lifespan SR+MA: PRISMA 2020 (main), PRISMA-P for the protocol, PRISMA-S for searches; ROSES if framed as an environmental evidence synthesis; appraisal via SYRCLE-style domains (a tool, not a reporting guideline).""",
 examples=[("Clinical","PRISMA 2020."),("Observational","MOOSE."),("Diagnostic","PRISMA-DTA."),("Scoping","PRISMA-ScR."),("Qualitative","ENTREQ.")],
 mistakes=["Using an outdated version.","Treating a checklist as quality.","Not justifying N/A items."],
 misconceptions=[("'Any PRISMA works.'","Match the extension."),("'ARRIVE for my review.'","It is for primary animal studies.")],
 controversies=["Which items are essential.","Checklist fatigue."],
 decision_tree=[("Standard SR?","PRISMA 2020 + P + S."),("Scoping?","PRISMA-ScR."),("No pooling?","SWiM."),("Qualitative?","ENTREQ.")],
 exercises=["Pick the guidelines for your review and download current versions.","Complete a checklist for a published review.","Find a guideline for your design via EQUATOR."],
 integrity="Do not claim adherence without completing the checklist.", further=["page2021","shamseer2015","rethlefsen2021","tricco2018","campbell2020","stroup2000","mcgrath2019dta","hutton2015","stewart2015","tong2012","haddaway2018roses"],
 application="**Milestone 13:** choose and complete the right checklists.", checklist=["Right guideline chosen","Current version","Checklist completed with locations"],
 quiz=[dict(q="Reporting guideline for scoping reviews?", opts=["PRISMA-ScR","PRISMA-NMA","MOOSE","ARRIVE"], ans=0, why="Tricco 2018."),
  dict(q="For observational study meta-analyses?", opts=["MOOSE","PRISMA-IPD","SWiM","ENTREQ"], ans=0, why="Stroup 2000."),
  dict(q="Is ARRIVE a reporting guideline for your review?", opts=["No - for primary animal studies","Yes","Only for fish","Only for plants"], ans=0, why="Scope."),
  dict(q="Where to find other guidelines?", opts=["EQUATOR Network","Social media","Wikipedia only","Random"], ans=0, why="Library."),
  dict(q="Completing a checklist proves...", opts=["Reporting completeness, not quality","Quality","Bias absence","Novelty"], ans=0, why="Reporting only.")])

add(id=77, title="Journal selection and predatory publishing", last_verified=V, prerequisites=["Module 75"],
 objectives=["Evaluate journal fit and policies from official sources.", "Recognise predatory-journal warning signs.", "Understand open access and fee models."],
 why="Choosing a journal affects review quality, visibility and cost; predatory journals harm authors and science.",
 plain="""Evaluate: **scope** (does it publish evidence syntheses in your field?), **indexing**, **peer review model**, **policies** (data sharing, AI use, registration), **open-access models and fees** (check the journal's own page; fees and waivers change), **editorial board and transparency**. Predatory journals lack genuine peer review and transparency; a modified Delphi consensus defined them (Cukier et al. 2020: 'Defining predatory journals and responding to the threat they pose' - cited as further reading, content not examined). Use institutional library advice and checklists.""",
 intermediate="""Read recent articles for quality, check editor and publisher credentials, confirm indexing from the *index's* own list (not the journal's claim), compare turnaround and policies. Never rely on this platform for current fees; verify on the official journal page. A decision to submit is yours; MetaLab never submits anything.""",
 advanced="""Beware hijacked journals and fake indexing claims. Consider discipline society journals, registered reports and overlay journals. Preprints before submission can speed feedback (check journal policy).""",
 assumptions=["Information verified from official pages at the time."],
 worked_example="""Create a comparison table for 3 candidate journals: scope fit (recent SRs in the field), indexing (verified on index site), peer-review model, APC/waivers (official page, dated), data/AI policies, typical turnaround (from the journal if stated). Record verification dates; do not copy from memory.""",
 examples=[("Clinical","Methods journals."),("Preclinical","Aging/biology journals."),("Ecology","Evidence synthesis journals."),("Education","Education reviews."),("Any","Mega-journals vs specialist.")],
 mistakes=["Trusting unsolicited invitations.","Not checking indexing at source.","Ignoring fees until acceptance.","Choosing for speed only."],
 misconceptions=[("'Open access = predatory.'","They are distinct."),("'High APC = quality.'","Not a measure.")],
 controversies=["Defining predatory.","APC equity."],
 decision_tree=[("Scope fit?","Check recent articles."),("Indexed (verified)?","Else caution."),("Policies acceptable?","Data/AI/registration."),("Cost feasible?","Waivers?")],
 exercises=["Build a 3-journal comparison with dated sources.","Check one journal's indexing at the index.","Write a submission checklist."],
 integrity="Submit only with your approval; no authorship-for-pay; verify fees and policies on official pages.", further=["cukier2020","page2021", "pieper2022"],
 application="**Milestone 14:** journal fit check from official pages (you decide).", checklist=["Official pages read","Indexing verified","Policies compared","Costs noted with date"],
 quiz=[dict(q="Verify indexing claims...", opts=["At the index's own site","In the journal email","On social media","Never"], ans=0, why="Avoid false claims."),
  dict(q="Current APC should be taken from...", opts=["The official journal page (dated)","Memory","A blog","MetaLab"], ans=0, why="Changes."),
  dict(q="Is open access the same as predatory?", opts=["No","Yes","Sometimes by definition","Always"], ans=0, why="Distinct."),
  dict(q="Who decides to submit?", opts=["You","The platform","A bot","Reviewers"], ans=0, why="Rule."),
  dict(q="A warning sign is...", opts=["Aggressive solicitation and opaque peer review","Open access","Society ownership","Preprint policy"], ans=0, why="Predatory features.")])

add(id=78, title="Submission and peer review: responding well", last_verified=V, prerequisites=["Module 77"],
 objectives=["Prepare cover letter, checklist and submission package.", "Write a point-by-point response letter.", "Handle rejection and appeals professionally."],
 why="Most manuscripts are revised; a clear, courteous, evidence-based response matters.",
 plain="""Package: manuscript, PRISMA checklist, cover letter (why it fits; no overclaiming), supplements, data/code statements, registration details, author contributions (CRediT), conflicts. After review: respond **point by point**, quote each comment, state the change (with location) or a respectful reasoned rebuttal. Track changes. Appeals only with specific factual grounds.""",
 intermediate="""Do not guarantee acceptance to anyone. Keep a record of versions and the audit trail of analytic changes: reviewers may request new analyses - label them *post hoc* in the manuscript. Corrections and retractions exist if errors are found later; handle them transparently.""",
 advanced="""Responding to statistical reviewers: provide reproducible code; sensitivity analyses requested should be added as supplementary and described as post hoc if not pre-specified. Disagreements with reviewers: cite evidence, remain civil, and consider editor communication.""",
 assumptions=["All new analyses are logged as deviations."],
 worked_example="""Reviewer 2, comment 3: 'Why was REML used?' Response: 'Thank you. REML was pre-specified (Protocol section 4.2). We added a sensitivity analysis with Paule-Mandel (Supplement Table S5); conclusions are unchanged (pooled estimate X vs Y). Manuscript p. 9, lines 12-15.' (numbers from stored outputs).""",
 examples=[("Any","Desk rejection -> revise scope."),("Statistics","Extra sensitivity analyses."),("Ethics","COI clarifications."),("Methods","Registration queries."),("Data","Share code.")],
 mistakes=["Defensive tone.","Ignoring comments.","Unlogged new analyses.","Overpromising."],
 misconceptions=[("'Rejection means bad science.'","Fit and priorities vary."),("'Reviewers are always right.'","Respond with evidence.")],
 controversies=["Open peer review.","Appeals."],
 decision_tree=[("Comment valid?","Change and cite location."),("Disagree?","Reasoned rebuttal with evidence."),("New analysis?","Label post hoc.")],
 exercises=["Draft a response to three mock reviewer comments.","Write a cover letter without overclaiming.","List files for a reproducibility package."],
 integrity="No guarantee of publication; transparent labelling of post hoc analyses; respectful conduct.", further=["page2021","moher2015", "cumpston2019"],
 application="**Milestone 14:** assemble submission documents (you decide whether/where to submit).", checklist=["Cover letter","Checklist","CRediT","COI","Reproducibility package"],
 quiz=[dict(q="New analyses requested in review should be...", opts=["Labelled post hoc/sensitivity","Hidden","Presented as pre-specified","Ignored"], ans=0, why="Honesty."),
  dict(q="Response letters should be...", opts=["Point by point with locations","Vague","Angry","Optional"], ans=0, why="Clarity."),
  dict(q="Cover letters should...", opts=["Explain fit without overclaiming","Guarantee impact","Insult reviewers","Be omitted"], ans=0, why="Professional."),
  dict(q="Appeals require...", opts=["Specific factual grounds","Pressure","Emails to all editors","Nothing"], ans=0, why="Process."),
  dict(q="Who submits?", opts=["You","MetaLab","Bots","Reviewers"], ans=0, why="Platform never submits.")])

add(id=82, title="Open science, data governance and reproducibility", last_verified=V, prerequisites=["Modules 75"],
 objectives=["Apply FAIR principles to review data and code.", "Choose repositories and licences (owner's decision).", "Explain when ethics review may or may not apply."],
 why="Reproducible reviews build trust and allow reuse.",
 plain="""Share: protocol, search strategies, raw exports (if licences allow), screening decisions, extraction data, analysis code, environment details. **FAIR** (Findable, Accessible, Interoperable, Reusable; Wilkinson et al. 2016) guides data stewardship: persistent IDs (DOI), rich metadata, open formats, clear licences. Archive in a repository with a DOI (e.g. Zenodo or OSF - check their terms). MetaLab's reproducibility ZIP packages records, code, SAP and a hash manifest.""",
 intermediate="""Copyright: do not redistribute full-text PDFs; share extracted data and citations. Personal data: reviews of published studies usually involve no personal data, but IPD meta-analysis does. **Ethics review requirements vary by institution and country; do not assume a systematic review is exempt - ask your ethics office.** Choose licences (e.g. for data/code/text) deliberately; that is a decision for the data owner.""",
 advanced="""Computational reproducibility: lock package versions (renv, requirements), record session info, provide a one-command rebuild, test with a clean environment. Use version control with tagged releases. Machine-readable metadata (CSV + data dictionary) supports reuse.""",
 assumptions=["Licences allow sharing.","Data contain no personal data unless handled properly."],
 worked_example="""Package: protocol.pdf, search_log.csv, references.csv, screening.csv, extraction_all_versions.csv, analysis_dataset.csv, analysis.R, SAP_draft.md, prisma_flow.svg, audit_log.csv, MANIFEST.txt (SHA-256). Archive with a DOI; cite it in the Data availability statement.""",
 examples=[("Clinical","IPD governance."),("Preclinical","Raw lifespan tables."),("Ecology","Spatial data."),("Education","Student data privacy."),("All","Version-locked code.")],
 mistakes=["Sharing PDFs.","No licence.","No session info.","Assuming ethics exemption."],
 misconceptions=[("'Open means no restrictions.'","Licences and privacy apply."),("'Reviews never need ethics review.'","Depends on context.")],
 controversies=["Open peer review.","Data licences."],
 decision_tree=[("Personal data?","Ethics + governance."),("Copyright full texts?","Do not share."),("Licence chosen?","Owner decides.")],
 exercises=["Export the Virtual Lab package and inspect it.","Write a Data availability statement.","List what you can and cannot share."],
 integrity="No redistribution of copyrighted PDFs; do not publish private research data without consent/approval.", further=["wilkinson2016","page2021ee", "sandve2013"],
 application="**Milestone 14:** assemble and archive the reproducibility package (archiving/publishing is your decision).", checklist=["Package complete","Licences considered","Ethics query made","Data statement written"],
 quiz=[dict(q="FAIR stands for...", opts=["Findable, Accessible, Interoperable, Reusable","Fast, Accurate, Independent, Real","Free, Open, Public, Shared","None"], ans=0, why="Wilkinson 2016."),
  dict(q="Do systematic reviews never need ethics review?", opts=["Not always exempt - ask your ethics office","Never need","Always need","Only for IPD"], ans=0, why="Varies."),
  dict(q="Should full-text PDFs be shared?", opts=["No, respect copyright","Yes","Only for preprints","Only OA"], ans=0, why="Copyright."),
  dict(q="Who chooses the data licence?", opts=["The owner","MetaLab","Reviewers","Journals"], ans=0, why="Decision."),
  dict(q="The reproducibility ZIP includes...", opts=["Records, code, SAP, manifest","Only text","PDFs","Passwords"], ans=0, why="Design.")])

add(id=11, title="Supplementary searching: citations, registries and grey literature", last_verified=V, prerequisites=["Modules 9, 10"],
 objectives=["Plan backward/forward citation chasing and registry searches.", "Search preprints and grey literature transparently.", "Explain how these methods affect completeness and publication bias."],
 why="Database searches miss studies; supplementary methods find some of them and reduce publication bias.",
 plain="""**Backward chasing**: check reference lists of included studies; **forward chasing**: find papers citing them (OpenAlex, Web of Science, Scopus); **related articles**; **registries** (trials/protocols) for unpublished studies; **preprints**; **theses and reports**; **contacting experts/authors** (with your approval). Record each method, date, source and yield.""",
 intermediate="""Yield is usually small but sometimes decisive. Use the same eligibility criteria; screen results like any record (and deduplicate). For living reviews, set surveillance alerts and document updates. Grey literature raises quality-assessment issues: report that these are non-peer-reviewed.""",
 advanced="""Citation chasing algorithms can be automated via open APIs; combine with deduplication and PRISMA tracking of citation-search records. Publication bias arguments: unpublished/negative results appear in registries, theses and preprints.""",
 assumptions=["Methods and dates are logged."],
 worked_example="""Included 8 studies: backward chasing yields 140 references (95 unique), forward chasing 210 citing papers (150 unique); after dedup against the main search: 12 new records; 2 eligible, both preprints. Report in the PRISMA flow as 'other methods'.""",
 examples=[("Clinical","Trial registries."),("Preclinical","Preprints and theses."),("Ecology","Government reports."),("Education","Conference papers."),("All","Expert contact.")],
 mistakes=["Not logging yield.","Skipping dedup.","Ignoring preprint status."],
 misconceptions=[("'Database search is enough.'","Coverage gaps exist."),("'Grey literature is lower quality by definition.'","Appraise it.")],
 controversies=["How much supplementary searching.","Value of contacting experts."],
 decision_tree=[("Included studies identified?","Chase backward/forward."),("Registries relevant?","Search."),("Preprints?","Check published status.")],
 exercises=["Chase citations for two included studies and log yield.","Search a registry for your topic.","Write a grey-literature plan."],
 integrity="Contact experts/authors only with your approval; report non-peer-reviewed sources as such.", further=["rethlefsen2021","page2021ee","gusenbauer2020"],
 application="**Milestone 5:** supplementary search plan with logging.", checklist=["Citation chasing logged","Registries searched","Preprints handled","Yield recorded"],
 quiz=[dict(q="Forward citation chasing finds...", opts=["Papers citing included studies","References of included studies","Duplicates","Registries"], ans=0, why="Definition."),
  dict(q="Why search registries?", opts=["To find unpublished/ongoing studies","To find authors","For fees","For MeSH"], ans=0, why="Publication bias."),
  dict(q="Supplementary results must be...", opts=["Deduplicated and screened","Added unscreened","Ignored","Merged"], ans=0, why="Same process."),
  dict(q="Grey literature should be...", opts=["Reported as non-peer-reviewed","Hidden","Excluded always","Quality-assumed"], ans=0, why="Transparency."),
  dict(q="Contacting experts requires...", opts=["Your approval and a transparent approach","Nothing","Automation","Payment"], ans=0, why="Rule.")])

add(id=12, title="Search reproducibility: logs, versions and appendices", last_verified=V, prerequisites=["Modules 10, 11"],
 objectives=["Log every search with required fields.", "Version searches and track updates.", "Generate a reproducible search appendix."],
 why="PRISMA-S asks for enough detail to reproduce a search; without logs you cannot.",
 plain="""For each search record: database, platform/interface, date, **exact query** (copy-paste), filters/limits, results count, export count, searcher, notes, access limits, raw export file. Version a search when you change it (v1, v2...) and keep old versions. Re-running months later returns different counts (new records, indexing); record the date and consider update searches.""",
 intermediate="""Use the Search Log to export a CSV appendix. Never claim a search was run unless it was. Report searches that returned nothing or could not be run. PRISMA-S (Rethlefsen et al. 2021) lists items to report; PRESS (McGowan et al. 2016) is for peer review of strategies.""",
 advanced="""Script searches via APIs when allowed (store raw JSON). For living reviews, run date-restricted updates with overlap windows and dedupe. Hash raw exports (SHA-256) for integrity, as MetaLab does for imports.""",
 assumptions=["Searches run by you; logs created at the time."],
 worked_example="""Search v1: PubMed, 2026-11-26, '(Drosophila) AND (lifespan OR longevity) AND (dietary restriction OR diet)', 869 results (this is a real logged count from the topic scan). Search v2 adds 'fruit fly' on a later date; log both with counts and keep both queries.""",
 examples=[("All","Search appendix CSV."),("Living reviews","Update logs."),("Teams","Operator field."),("Restricted access","Access limits."),("APIs","Raw JSON.")],
 mistakes=["No date.","Overwriting old queries.","Not recording failures.","Editing exports."],
 misconceptions=[("'The query is enough.'","Platform and date matter."),("'Counts will match later.'","They change.")],
 controversies=["How much detail.","Archiving results."],
 decision_tree=[("Changed the query?","New version."),("Database unavailable?","Log limitation."),("Update needed?","Re-run with date.")],
 exercises=["Log three searches with all fields.","Export the search appendix.","Write the search-limitations sentence."],
 integrity="Never claim searches that were not run; report limitations.", further=["rethlefsen2021","mcgowan2016","page2021ee"],
 application="**Milestone 5:** complete the Search Log and export the appendix.", checklist=["All fields logged","Versions kept","Raw exports hashed/stored","Appendix exported"],
 quiz=[dict(q="Which is required in a search log?", opts=["Exact query and date","Only database name","Only counts","Only author"], ans=0, why="Reproducibility."),
  dict(q="Why version searches?", opts=["Track changes and updates","Style","Fees","Speed"], ans=0, why="Audit."),
  dict(q="Counts change over time because...", opts=["Records are added/indexed","Bugs only","Never change","Caching"], ans=0, why="Dynamic databases."),
  dict(q="Failed/unavailable databases should be...", opts=["Reported as limitations","Hidden","Claimed searched","Replaced silently"], ans=0, why="Honesty."),
  dict(q="Raw exports should be...", opts=["Stored unchanged (and hashed)","Edited","Deleted","Shared with PDFs"], ans=0, why="Provenance.")])
